'use strict';const STORAGE_KEY = 'mijourney.exercises.v1';const form = document.querySelector('#exercise-form');const list = document.querySelector('#exercise-list');const emptyState = document.querySelector('#empty-state');const count = document.querySelector('#record-count');const status = document.querySelector('#status');const numberFormat = new Intl.NumberFormat('es-MX',{maximumFractionDigits: 2});function validExercise(item){return item && typeof item.id === 'string' && typeof item.name === 'string' && item.name.trim().length > 0 && item.name.length <= 80 && Number.isInteger(item.sets)&& item.sets >= 1 && item.sets <= 1000 && Number.isInteger(item.reps)&& item.reps >= 1 && item.reps <= 10000 && Number.isFinite(item.weight)&& item.weight >= 0 && item.weight <= 10000;}function loadExercises(){try{const saved = localStorage.getItem(STORAGE_KEY);if(saved === null)return[];const parsed = JSON.parse(saved);if(!Array.isArray(parsed)|| !parsed.every(validExercise))throw new Error('Datos inválidos');return parsed;}catch{status.textContent = 'No se pudieron recuperar los registros. Comprueba que el almacenamiento local esté disponible.';return[];}}let exercises = loadExercises();function saveExercises(next){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));exercises = next;renderExercises();return true;}catch{status.textContent = 'No se pudo guardar el cambio. Revisa el espacio o los permisos de almacenamiento del navegador e inténtalo de nuevo.';return false;}}function renderExercises(){list.replaceChildren();emptyState.hidden = exercises.length > 0;count.textContent = `${exercises.length} ${exercises.length === 1 ? 'registro' : 'registros'}`;for(const exercise of exercises){const card = document.createElement('li');card.className = 'exercise-card';const heading = document.createElement('div');heading.className = 'card-heading';const title = document.createElement('h3');title.textContent = exercise.name;const remove = document.createElement('button');remove.type = 'button';remove.className = 'delete';remove.textContent = 'Eliminar';remove.setAttribute('aria-label',`Eliminar ${exercise.name}`);remove.addEventListener('click',()=>{const index = exercises.indexOf(exercise);if(saveExercises(exercises.filter((item)=> item !== exercise))){status.textContent = `Se eliminó ${exercise.name}.`;const buttons = list.querySelectorAll('.delete');(buttons[Math.min(index,buttons.length - 1)]|| form.elements.name).focus();}});heading.append(title,remove);const metrics = document.createElement('dl');metrics.className = 'metrics';for(const[label,value]of[['Series',exercise.sets],['Repeticiones',exercise.reps],['Peso (kg)',exercise.weight]]){const group = document.createElement('div');const term = document.createElement('dt');term.textContent = label;const detail = document.createElement('dd');detail.textContent = numberFormat.format(value);group.append(term,detail);metrics.append(group);}card.append(heading,metrics);list.append(card);}}form.addEventListener('submit',(event)=>{event.preventDefault();const nameInput = form.elements.name;nameInput.setCustomValidity(nameInput.value.trim()? '' : 'Escribe el nombre del ejercicio.');if(!form.reportValidity())return;const exercise ={id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,name: nameInput.value.trim(),sets: Number(form.elements.sets.value),reps: Number(form.elements.reps.value),weight: Number(form.elements.weight.value),};if(!validExercise(exercise))return;if(saveExercises([exercise,...exercises])){form.reset();nameInput.focus();status.textContent = `${exercise.name} se registró correctamente.`;}});form.elements.name.addEventListener('input',()=> form.elements.name.setCustomValidity(''));renderExercises();